def skill():
    x, C = symbols('x C')
    fp = 6*x + 2
    f = integrate(fp, x) + C
    C0 = solve(f.subs(x, 1) - 10, C)[0]
    return f.subs(C, C0).subs(x, 2)

def standard():
    x, t = symbols('x t')
    cs = symbols('c0:6')
    f = sum(c*x**i for i, c in enumerate(cs))
    eq = expand(integrate(f.subs(x, t), (t, 0, x)) - (x*f - 2*x**3 - x**2))
    s = solve(Poly(eq, x).all_coeffs() + [f.subs(x, 1) - 10], cs, dict=True)
    return f.subs(s[0]).subs(x, 2)

def unique():
    x, t = symbols('x t')
    cs = symbols('c0:6')
    f = sum(c*x**i for i, c in enumerate(cs))
    eq = expand(integrate(f.subs(x, t), (t, 0, x)) - (x*f - 2*x**3 - x**2))
    s = solve(Poly(eq, x).all_coeffs() + [f.subs(x, 1) - 10], cs, dict=True)
    return sorted({f.subs(d).subs(x, 2) for d in s})
